select public.upsert_bank_question($json${"id":"cartas2-easy-001","type":"choice","level":"easy","testament":"nt","book":"ROM","chapter":3,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Segundo Romanos 3:23, quem pecou e está destituído da glória de Deus?","bible_ref":"Romanos 3:23","verse_text":"porque todos pecaram, e estão destituídos da glória de Deus;"},"fr":{"prompt":"Selon Romains 3:23, qui a péché et est privé de la gloire de Dieu ?","bible_ref":"Romains 3:23","verse_text":"Car tous ont péché et sont privés de la gloire de Dieu;"},"en":{"prompt":"According to Romans 3:23, who have sinned and come short of the glory of God?","bible_ref":"Romans 3:23","verse_text":"For all have sinned, and come short of the glory of God;"},"es":{"prompt":"Según Romanos 3:23, ¿quiénes pecaron y están destituidos de la gloria de Dios?","bible_ref":"Romanos 3:23","verse_text":"Por cuanto todos pecaron, y están destituídos de la gloria de Dios;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Todos"},"fr":{"text":"Tous"},"en":{"text":"All"},"es":{"text":"Todos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Só os gentios"},"fr":{"text":"Seulement les païens"},"en":{"text":"Only the Gentiles"},"es":{"text":"Solo los gentiles"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Só os reis"},"fr":{"text":"Seulement les rois"},"en":{"text":"Only the kings"},"es":{"text":"Solo los reyes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ninguém"},"fr":{"text":"Personne"},"en":{"text":"No one"},"es":{"text":"Nadie"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-002","type":"choice","level":"easy","testament":"nt","book":"1CO","chapter":13,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo 1 Coríntios 13:4, como é o amor?","bible_ref":"1 Coríntios 13:4","verse_text":"O amor é paciente, é bondoso; o amor não é invejoso; o amor não é orgulhoso, não é arrogante."},"fr":{"prompt":"Selon 1 Corinthiens 13:4, comment est la charité ?","bible_ref":"1 Corinthiens 13:4","verse_text":"La charité est patiente, elle est pleine de bonté; la charité n’est point envieuse; la charité ne se vante point, elle ne s’enfle point d’orgueil,"},"en":{"prompt":"According to 1 Corinthians 13:4, what is charity like?","bible_ref":"1 Corinthians 13:4","verse_text":"Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,"},"es":{"prompt":"Según 1 Corintios 13:4, ¿cómo es la caridad?","bible_ref":"1 Corintios 13:4","verse_text":"La caridad es sufrida, es benigna; la caridad no tiene envidia, la caridad no hace sinrazón, no se ensancha;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Paciente e bondoso"},"fr":{"text":"Patiente et pleine de bonté"},"en":{"text":"It suffereth long and is kind"},"es":{"text":"Sufrida y benigna"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Orgulhoso e invejoso"},"fr":{"text":"Orgueilleuse et envieuse"},"en":{"text":"Proud and envious"},"es":{"text":"Orgullosa y envidiosa"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rápido a irar-se"},"fr":{"text":"Prompte à se mettre en colère"},"en":{"text":"Quick to anger"},"es":{"text":"Pronta para airarse"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Triste e severo"},"fr":{"text":"Triste et sévère"},"en":{"text":"Sad and severe"},"es":{"text":"Triste y severa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-003","type":"choice","level":"easy","testament":"nt","book":"1CO","chapter":12,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo 1 Coríntios 12:12, o corpo é um só, mas tem muitos…","bible_ref":"1 Coríntios 12:12","verse_text":"Porque assim como o corpo é um, e tem muitos membros, e todos os membros deste único corpo, sendo muitos, compõem um só corpo; assim também é Cristo."},"fr":{"prompt":"Selon 1 Corinthiens 12:12, le corps est un, mais il a plusieurs…","bible_ref":"1 Corinthiens 12:12","verse_text":"Car, comme le corps est un et a plusieurs membres, et comme tous les membres du corps, malgré leur nombre, ne forment qu’un seul corps, ainsi en est-il de Christ."},"en":{"prompt":"According to 1 Corinthians 12:12, the body is one, but has many…","bible_ref":"1 Corinthians 12:12","verse_text":"For as the body is one, and hath many members, and all the members of that one body, being many, are one body: so also is Christ."},"es":{"prompt":"Según 1 Corintios 12:12, el cuerpo es uno, pero tiene muchos…","bible_ref":"1 Corintios 12:12","verse_text":"Porque de la manera que el cuerpo es uno, y tiene muchos miembros, empero todos los miembros del cuerpo, siendo muchos, son un cuerpo, así también Cristo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Membros"},"fr":{"text":"Membres"},"en":{"text":"Members"},"es":{"text":"Miembros"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nomes"},"fr":{"text":"Noms"},"en":{"text":"Names"},"es":{"text":"Nombres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Corações"},"fr":{"text":"Cœurs"},"en":{"text":"Hearts"},"es":{"text":"Corazones"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rostos"},"fr":{"text":"Visages"},"en":{"text":"Faces"},"es":{"text":"Rostros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-004","type":"choice","level":"easy","testament":"nt","book":"2CO","chapter":9,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo 2 Coríntios 9:7, quem é que Deus ama?","bible_ref":"2 Coríntios 9:7","verse_text":"Cada qual faça como propõe em seu coração, não com tristeza, ou por obrigação; porque Deus ama ao que dá com alegria."},"fr":{"prompt":"Selon 2 Corinthiens 9:7, qui Dieu aime-t-il ?","bible_ref":"2 Corinthiens 9:7","verse_text":"Que chacun donne comme il l’a résolu en son cœur, sans tristesse ni contrainte; car Dieu aime celui qui donne avec joie."},"en":{"prompt":"According to 2 Corinthians 9:7, whom does God love?","bible_ref":"2 Corinthians 9:7","verse_text":"Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver."},"es":{"prompt":"Según 2 Corintios 9:7, ¿a quién ama Dios?","bible_ref":"2 Corintios 9:7","verse_text":"Cada uno dé como propuso en su corazón: no con tristeza, ó por necesidad; porque Dios ama el dador alegre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quem dá com alegria"},"fr":{"text":"Celui qui donne avec joie"},"en":{"text":"A cheerful giver"},"es":{"text":"El dador alegre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quem dá com tristeza"},"fr":{"text":"Celui qui donne avec tristesse"},"en":{"text":"A grudging giver"},"es":{"text":"El que da con tristeza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quem dá por obrigação"},"fr":{"text":"Celui qui donne par contrainte"},"en":{"text":"One who gives of necessity"},"es":{"text":"El que da por necesidad"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quem nunca pede nada"},"fr":{"text":"Celui qui ne demande jamais rien"},"en":{"text":"One who never asks for anything"},"es":{"text":"El que nunca pide nada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-005","type":"choice","level":"easy","testament":"nt","book":"GAL","chapter":6,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Completa Gálatas 6:7: «o que o ser humano semear, isso também…»","bible_ref":"Gálatas 6:7","verse_text":"Não vos enganeis: Deus não se deixa escarnecer; pois, o que o ser humano semear, isso também colherá."},"fr":{"prompt":"Complète Galates 6:7 : « Ce qu’un homme aura semé, il le… »","bible_ref":"Galates 6:7","verse_text":"Ne vous y trompez pas: on ne se moque pas de Dieu. Ce qu’un homme aura semé, il le moissonnera aussi."},"en":{"prompt":"Complete Galatians 6:7: “whatsoever a man soweth, that shall he also…”","bible_ref":"Galatians 6:7","verse_text":"Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap."},"es":{"prompt":"Completa Gálatas 6:7: «todo lo que el hombre sembrare, eso también…»","bible_ref":"Gálatas 6:7","verse_text":"No os engañéis: Dios no puede ser burlado: que todo lo que el hombre sembrare, eso también segará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"colherá"},"fr":{"text":"moissonnera"},"en":{"text":"reap"},"es":{"text":"segará"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"venderá"},"fr":{"text":"vendra"},"en":{"text":"sell"},"es":{"text":"venderá"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"esquecerá"},"fr":{"text":"oubliera"},"en":{"text":"forget"},"es":{"text":"olvidará"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"perderá"},"fr":{"text":"perdra"},"en":{"text":"lose"},"es":{"text":"perderá"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-006","type":"choice","level":"easy","testament":"nt","book":"EPH","chapter":2,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Efésios 2:8, o que nos salva, por meio da fé?","bible_ref":"Efésios 2:8","verse_text":"Porque pela graça sois salvos, por meio da fé; e isto não vem de vós; é dom de Deus;"},"fr":{"prompt":"Selon Éphésiens 2:8, qu’est-ce qui nous sauve, par le moyen de la foi ?","bible_ref":"Éphésiens 2:8","verse_text":"Car c’est par la grâce que vous êtes sauvés, par le moyen de la foi. Et cela ne vient pas de vous, c’est le don de Dieu."},"en":{"prompt":"According to Ephesians 2:8, what saves us, through faith?","bible_ref":"Ephesians 2:8","verse_text":"For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"},"es":{"prompt":"Según Efesios 2:8, ¿qué nos salva por la fe?","bible_ref":"Efesios 2:8","verse_text":"Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es don de Dios:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A graça"},"fr":{"text":"La grâce"},"en":{"text":"Grace"},"es":{"text":"La gracia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"As nossas obras"},"fr":{"text":"Nos œuvres"},"en":{"text":"Our works"},"es":{"text":"Nuestras obras"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O dinheiro"},"fr":{"text":"L’argent"},"en":{"text":"Money"},"es":{"text":"El dinero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A nossa força"},"fr":{"text":"Notre force"},"en":{"text":"Our strength"},"es":{"text":"Nuestra fuerza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-007","type":"choice","level":"easy","testament":"nt","book":"PHP","chapter":4,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Filipenses 4:4, quando devemos alegrar-nos no Senhor?","bible_ref":"Filipenses 4:4","verse_text":"Alegrai-vos sempre no Senhor. Volto a dizer: alegrai-vos."},"fr":{"prompt":"Selon Philippiens 4:4, quand devons-nous nous réjouir dans le Seigneur ?","bible_ref":"Philippiens 4:4","verse_text":"Réjouissez-vous toujours dans le Seigneur; je le répète, réjouissez-vous."},"en":{"prompt":"According to Philippians 4:4, when should we rejoice in the Lord?","bible_ref":"Philippians 4:4","verse_text":"Rejoice in the Lord alway: and again I say, Rejoice."},"es":{"prompt":"Según Filipenses 4:4, ¿cuándo debemos gozarnos en el Señor?","bible_ref":"Filipenses 4:4","verse_text":"Gozaos en el Señor siempre: otra vez digo: Que os gocéis."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sempre"},"fr":{"text":"Toujours"},"en":{"text":"Always"},"es":{"text":"Siempre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Só nos dias de festa"},"fr":{"text":"Seulement les jours de fête"},"en":{"text":"Only on feast days"},"es":{"text":"Solo en los días de fiesta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Só quando tudo corre bem"},"fr":{"text":"Seulement quand tout va bien"},"en":{"text":"Only when all goes well"},"es":{"text":"Solo cuando todo va bien"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Só de manhã"},"fr":{"text":"Seulement le matin"},"en":{"text":"Only in the morning"},"es":{"text":"Solo por la mañana"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-008","type":"choice","level":"easy","testament":"nt","book":"COL","chapter":3,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Segundo Colossenses 3:23, devemos fazer tudo de coração, como para quem?","bible_ref":"Colossenses 3:23","verse_text":"E tudo quanto fizerdes, fazei de coração, como para o Senhor, e não para as pessoas."},"fr":{"prompt":"Selon Colossiens 3:23, nous devons tout faire de bon cœur, comme pour qui ?","bible_ref":"Colossiens 3:23","verse_text":"Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur et non pour des hommes,"},"en":{"prompt":"According to Colossians 3:23, we should do everything heartily, as to whom?","bible_ref":"Colossians 3:23","verse_text":"And what soever ye do, do it heartily, as to the Lord, and not unto men;"},"es":{"prompt":"Según Colosenses 3:23, debemos hacerlo todo de ánimo, ¿como para quién?","bible_ref":"Colosenses 3:23","verse_text":"Y todo lo que hagáis, hacedlo de ánimo, como al Señor, y no á los hombres;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Para o Senhor"},"fr":{"text":"Pour le Seigneur"},"en":{"text":"To the Lord"},"es":{"text":"Para el Señor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Para os vizinhos"},"fr":{"text":"Pour les voisins"},"en":{"text":"To the neighbours"},"es":{"text":"Para los vecinos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Para nós mesmos"},"fr":{"text":"Pour nous-mêmes"},"en":{"text":"To ourselves"},"es":{"text":"Para nosotros mismos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Para o rei"},"fr":{"text":"Pour le roi"},"en":{"text":"To the king"},"es":{"text":"Para el rey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-009","type":"choice","level":"easy","testament":"nt","book":"1TH","chapter":5,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Segundo 1 Tessalonicenses 5:18, em que devemos dar graças?","bible_ref":"1 Tessalonicenses 5:18","verse_text":"Agradecei em tudo, pois essa é a vontade de Deus em Cristo Jesus para vós mesmos."},"fr":{"prompt":"Selon 1 Thessaloniciens 5:18, en quoi devons-nous rendre grâces ?","bible_ref":"1 Thessaloniciens 5:18","verse_text":"Rendez grâces en toutes choses, car c’est à votre égard la volonté de Dieu en Jésus-Christ."},"en":{"prompt":"According to 1 Thessalonians 5:18, in what should we give thanks?","bible_ref":"1 Thessalonians 5:18","verse_text":"In every thing give thanks: for this is the will of God in Christ Jesus concerning you."},"es":{"prompt":"Según 1 Tesalonicenses 5:18, ¿en qué debemos dar gracias?","bible_ref":"1 Tesalonicenses 5:18","verse_text":"Dad gracias en todo; porque esta es la voluntad de Dios para con vosotros en Cristo Jesús."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em tudo"},"fr":{"text":"En toutes choses"},"en":{"text":"In every thing"},"es":{"text":"En todo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Só nas coisas boas"},"fr":{"text":"Seulement dans les bonnes choses"},"en":{"text":"Only in good things"},"es":{"text":"Solo en las cosas buenas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Só às refeições"},"fr":{"text":"Seulement aux repas"},"en":{"text":"Only at meals"},"es":{"text":"Solo en las comidas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Só ao sábado"},"fr":{"text":"Seulement le jour du sabbat"},"en":{"text":"Only on the sabbath"},"es":{"text":"Solo el sábado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-010","type":"choice","level":"easy","testament":"nt","book":"1TI","chapter":4,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo 1 Timóteo 4:12, o que é que ninguém devia desprezar em Timóteo?","bible_ref":"1 Timóteo 4:12","verse_text":"Ninguém despreze a tua juventude, mas sê exemplo aos crentes, na palavra, no comportamento, no amor, em espírito, na fé, e na pureza."},"fr":{"prompt":"Selon 1 Timothée 4:12, qu’est-ce que personne ne devait mépriser chez Timothée ?","bible_ref":"1 Timothée 4:12","verse_text":"Que personne ne méprise ta jeunesse; mais sois un modèle pour les fidèles, en parole, en conduite, en charité, en foi, en pureté."},"en":{"prompt":"According to 1 Timothy 4:12, what should no man despise in Timothy?","bible_ref":"1 Timothy 4:12","verse_text":"Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity."},"es":{"prompt":"Según 1 Timoteo 4:12, ¿qué no debía nadie tener en poco en Timoteo?","bible_ref":"1 Timoteo 4:12","verse_text":"Ninguno tenga en poco tu juventud; pero sé ejemplo de los fieles en palabra, en conversación, en caridad, en espíritu, en fe, en limpieza."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua juventude"},"fr":{"text":"Sa jeunesse"},"en":{"text":"His youth"},"es":{"text":"Su juventud"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A sua família"},"fr":{"text":"Sa famille"},"en":{"text":"His family"},"es":{"text":"Su familia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A sua pobreza"},"fr":{"text":"Sa pauvreté"},"en":{"text":"His poverty"},"es":{"text":"Su pobreza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A sua terra"},"fr":{"text":"Son pays"},"en":{"text":"His country"},"es":{"text":"Su tierra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-011","type":"choice","level":"easy","testament":"nt","book":"2TI","chapter":3,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Segundo 2 Timóteo 3:15, desde quando conhecia Timóteo as Sagradas Escrituras?","bible_ref":"2 Timóteo 3:15","verse_text":"e que desde tua infância conheceste as Sagradas Escrituras, que podem te fazer sábio para a salvação pela fé em Cristo Jesus."},"fr":{"prompt":"Selon 2 Timothée 3:15, depuis quand Timothée connaissait-il les saintes lettres ?","bible_ref":"2 Timothée 3:15","verse_text":"dès ton enfance, tu connais les saintes lettres, qui peuvent te rendre sage à salut par la foi en Jésus-Christ."},"en":{"prompt":"According to 2 Timothy 3:15, since when had Timothy known the holy scriptures?","bible_ref":"2 Timothy 3:15","verse_text":"And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus."},"es":{"prompt":"Según 2 Timoteo 3:15, ¿desde cuándo conocía Timoteo las Sagradas Escrituras?","bible_ref":"2 Timoteo 3:15","verse_text":"Y que desde la niñez has sabido las Sagradas Escrituras, las cuales te pueden hacer sabio para la salud por la fe que es en Cristo Jesús."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Desde a infância"},"fr":{"text":"Dès son enfance"},"en":{"text":"From a child"},"es":{"text":"Desde la niñez"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Desde que conheceu Paulo"},"fr":{"text":"Depuis qu’il avait connu Paul"},"en":{"text":"Since he met Paul"},"es":{"text":"Desde que conoció a Pablo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Desde que foi para Roma"},"fr":{"text":"Depuis son voyage à Rome"},"en":{"text":"Since he went to Rome"},"es":{"text":"Desde que fue a Roma"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Há poucos dias"},"fr":{"text":"Depuis peu de jours"},"en":{"text":"For only a few days"},