select public.upsert_bank_question($json${"id":"cartas2-easy-012","type":"choice","level":"easy","testament":"nt","book":"JAS","chapter":1,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Segundo Tiago 1:19, para que devemos ser prontos?","bible_ref":"Tiago 1:19","verse_text":"Portanto, meus amados irmãos, toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar;"},"fr":{"prompt":"Selon Jacques 1:19, à quoi devons-nous être prompts ?","bible_ref":"Jacques 1:19","verse_text":"Sachez-le, mes frères bien-aimés. Ainsi, que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère;"},"en":{"prompt":"According to James 1:19, what should we be swift to do?","bible_ref":"James 1:19","verse_text":"Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:"},"es":{"prompt":"Según Santiago 1:19, ¿para qué debemos ser prontos?","bible_ref":"Santiago 1:19","verse_text":"Por esto, mis amados hermanos, todo hombre sea pronto para oir, tardío para hablar, tardío para airarse:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Para ouvir"},"fr":{"text":"À écouter"},"en":{"text":"To hear"},"es":{"text":"Para oír"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Para falar"},"fr":{"text":"À parler"},"en":{"text":"To speak"},"es":{"text":"Para hablar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Para nos irarmos"},"fr":{"text":"À nous mettre en colère"},"en":{"text":"To be angry"},"es":{"text":"Para airarnos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Para julgar"},"fr":{"text":"À juger"},"en":{"text":"To judge"},"es":{"text":"Para juzgar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-013","type":"choice","level":"easy","testament":"nt","book":"1PE","chapter":3,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Segundo 1 Pedro 3:20, quantas pessoas foram salvas na arca, nos dias de Noé?","bible_ref":"1 Pedro 3:20","verse_text":"Estes são os que antigamente foram rebeldes, quando uma vez a paciência de Deus aguardava nos dias de Noé, enquanto era preparada a arca. Nela, poucas almas (isto é, oito) foram salvas por meio da água."},"fr":{"prompt":"Selon 1 Pierre 3:20, combien de personnes furent sauvées dans l’arche, aux jours de Noé ?","bible_ref":"1 Pierre 3:20","verse_text":"qui autrefois avaient été incrédules, lorsque la patience de Dieu se prolongeait, aux jours de Noé, pendant la construction de l’arche, dans laquelle un petit nombre de personnes, c’est-à-dire, huit, furent sauvées à travers l’eau."},"en":{"prompt":"According to 1 Peter 3:20, how many souls were saved in the ark, in the days of Noah?","bible_ref":"1 Peter 3:20","verse_text":"Which sometime were disobedient, when once the longsuffering of God waited in the days of Noah, while the ark was a preparing, wherein few, that is, eight souls were saved by water."},"es":{"prompt":"Según 1 Pedro 3:20, ¿cuántas personas fueron salvas en el arca, en los días de Noé?","bible_ref":"1 Pedro 3:20","verse_text":"Los cuales en otro tiempo fueron desobedientes, cuando una vez esperaba la paciencia de Dios en los días de Noé, cuando se aparejaba el arca; en la cual pocas, es á saber, ocho personas fueron salvas por agua."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Oito"},"fr":{"text":"Huit"},"en":{"text":"Eight"},"es":{"text":"Ocho"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Duas"},"fr":{"text":"Deux"},"en":{"text":"Two"},"es":{"text":"Dos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-014","type":"choice","level":"easy","testament":"nt","book":"1PE","chapter":5,"verse_start":6,"verse_end":7,"texts":{"pt":{"prompt":"Segundo 1 Pedro 5:6-7, porque devemos lançar sobre Deus toda a nossa ansiedade?","bible_ref":"1 Pedro 5:6-7","verse_text":"Humilhai-vos, pois, debaixo da poderosa mão de Deus, para que ele vos exalte no tempo adequado, lançando sobre ele toda a vossa ansiedade; porque ele tem cuidado de vós."},"fr":{"prompt":"Selon 1 Pierre 5:6-7, pourquoi devons-nous nous décharger sur Dieu de tous nos soucis ?","bible_ref":"1 Pierre 5:6-7","verse_text":"Humiliez-vous donc sous la puissante main de Dieu, afin qu’il vous élève au temps convenable; et déchargez-vous sur lui de tous vos soucis, car lui-même prend soin de vous."},"en":{"prompt":"According to 1 Peter 5:6-7, why should we cast all our care upon God?","bible_ref":"1 Peter 5:6-7","verse_text":"Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time: Casting all your care upon him; for he careth for you."},"es":{"prompt":"Según 1 Pedro 5:6-7, ¿por qué debemos echar en Dios toda nuestra solicitud?","bible_ref":"1 Pedro 5:6-7","verse_text":"Humillaos pues bajo la poderosa mano de Dios, para que él os ensalce cuando fuere tiempo; Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Porque ele tem cuidado de nós"},"fr":{"text":"Parce qu’il prend soin de nous"},"en":{"text":"Because he careth for us"},"es":{"text":"Porque él tiene cuidado de nosotros"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Porque ele nos vai castigar"},"fr":{"text":"Parce qu’il va nous punir"},"en":{"text":"Because he will punish us"},"es":{"text":"Porque nos va a castigar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Porque as preocupações são boas"},"fr":{"text":"Parce que les soucis sont bons"},"en":{"text":"Because worries are good"},"es":{"text":"Porque las preocupaciones son buenas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Porque ele está longe"},"fr":{"text":"Parce qu’il est loin"},"en":{"text":"Because he is far away"},"es":{"text":"Porque él está lejos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-015","type":"choice","level":"easy","testament":"nt","book":"1JN","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo 1 João 1:9, o que faz Deus se confessarmos os nossos pecados?","bible_ref":"1 João 1:9","verse_text":"Se confessarmos nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça."},"fr":{"prompt":"Selon 1 Jean 1:9, que fait Dieu si nous confessons nos péchés ?","bible_ref":"1 Jean 1:9","verse_text":"Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité."},"en":{"prompt":"According to 1 John 1:9, what does God do if we confess our sins?","bible_ref":"1 John 1:9","verse_text":"If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."},"es":{"prompt":"Según 1 Juan 1:9, ¿qué hace Dios si confesamos nuestros pecados?","bible_ref":"1 Juan 1:9","verse_text":"Si confesamos nuestros pecados, él es fiel y justo para que nos perdone nuestros pecados, y nos limpie de toda maldad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Perdoa-nos"},"fr":{"text":"Il nous les pardonne"},"en":{"text":"He forgives us"},"es":{"text":"Nos perdona"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Esquece-se de nós"},"fr":{"text":"Il nous oublie"},"en":{"text":"He forgets us"},"es":{"text":"Se olvida de nosotros"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Castiga-nos"},"fr":{"text":"Il nous punit"},"en":{"text":"He punishes us"},"es":{"text":"Nos castiga"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Afasta-se de nós"},"fr":{"text":"Il s’éloigne de nous"},"en":{"text":"He goes away from us"},"es":{"text":"Se aleja de nosotros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-016","type":"choice","level":"easy","testament":"nt","book":"REV","chapter":1,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Em Apocalipse 1:8, o Senhor diz que é o Alfa e que outra letra?","bible_ref":"Apocalipse 1:8","verse_text":"“Eu sou o Alfa e o Ômega, o princípio e o fim”,diz o Senhor, que é, e que era, e que virá, o Todo-Poderoso."},"fr":{"prompt":"Dans Apocalypse 1:8, le Seigneur dit qu’il est l’alpha et quelle autre lettre ?","bible_ref":"Apocalypse 1:8","verse_text":"Je suis l’alpha et l’oméga, dit le Seigneur Dieu, celui qui est, qui était, et qui vient, le Tout-Puissant."},"en":{"prompt":"In Revelation 1:8, the Lord says he is Alpha and which other letter?","bible_ref":"Revelation 1:8","verse_text":"I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty."},"es":{"prompt":"En Apocalipsis 1:8, el Señor dice que es el Alpha y ¿qué otra letra?","bible_ref":"Apocalipsis 1:8","verse_text":"Yo soy el Alpha y la Omega, principio y fin, dice el Señor, que es y que era y que ha de venir, el Todopoderoso."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O Ómega"},"fr":{"text":"L’oméga"},"en":{"text":"Omega"},"es":{"text":"La Omega"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O Beta"},"fr":{"text":"Le bêta"},"en":{"text":"Beta"},"es":{"text":"La Beta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O Gama"},"fr":{"text":"Le gamma"},"en":{"text":"Gamma"},"es":{"text":"La Gamma"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O Delta"},"fr":{"text":"Le delta"},"en":{"text":"Delta"},"es":{"text":"La Delta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-017","type":"choice","level":"easy","testament":"nt","book":"REV","chapter":21,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Apocalipse 21:4, o que limpará Deus dos olhos deles?","bible_ref":"Apocalipse 21:4","verse_text":"E Deus limpará toda lágrima dos olhos deles; e não haverá mais morte, nem pranto, nem clamor, nem mais haverá dor; porque as primeiras coisas já passaram.”"},"fr":{"prompt":"Selon Apocalypse 21:4, qu’est-ce que Dieu essuiera de leurs yeux ?","bible_ref":"Apocalypse 21:4","verse_text":"Il essuiera toute larme de leurs yeux, et la mort ne sera plus, et il n’y aura plus ni deuil, ni cri, ni douleur, car les premières choses ont disparu."},"en":{"prompt":"According to Revelation 21:4, what shall God wipe away from their eyes?","bible_ref":"Revelation 21:4","verse_text":"And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."},"es":{"prompt":"Según Apocalipsis 21:4, ¿qué limpiará Dios de los ojos de ellos?","bible_ref":"Apocalipsis 21:4","verse_text":"Y limpiará Dios toda lágrima de los ojos de ellos; y la muerte no será más; y no habrá más llanto, ni clamor, ni dolor: porque las primeras cosas son pasadas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Toda a lágrima"},"fr":{"text":"Toute larme"},"en":{"text":"All tears"},"es":{"text":"Toda lágrima"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Toda a poeira"},"fr":{"text":"Toute poussière"},"en":{"text":"All dust"},"es":{"text":"Todo polvo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Toda a luz"},"fr":{"text":"Toute lumière"},"en":{"text":"All light"},"es":{"text":"Toda luz"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Todo o sono"},"fr":{"text":"Tout sommeil"},"en":{"text":"All sleep"},"es":{"text":"Todo sueño"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-easy-018","type":"choice","level":"easy","testament":"nt","book":"REV","chapter":3,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Segundo Apocalipse 3:20, o que faz aquele que está à porta?","bible_ref":"Apocalipse 3:20","verse_text":"Eis que eu estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei até ele, e cearei com ele, e ele comigo."},"fr":{"prompt":"Selon Apocalypse 3:20, que fait celui qui se tient à la porte ?","bible_ref":"Apocalypse 3:20","verse_text":"Voici, je me tiens à la porte, et je frappe. Si quelqu’un entend ma voix et ouvre la porte, j’entrerai chez lui, je souperai avec lui, et lui avec moi."},"en":{"prompt":"According to Revelation 3:20, what does the one who stands at the door do?","bible_ref":"Revelation 3:20","verse_text":"Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me."},"es":{"prompt":"Según Apocalipsis 3:20, ¿qué hace el que está a la puerta?","bible_ref":"Apocalipsis 3:20","verse_text":"He aquí, yo estoy á la puerta y llamo: si alguno oyere mi voz y abriere la puerta, entraré á él, y cenaré con él, y él conmigo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Bate"},"fr":{"text":"Il frappe"},"en":{"text":"He knocks"},"es":{"text":"Llama"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Canta"},"fr":{"text":"Il chante"},"en":{"text":"He sings"},"es":{"text":"Canta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dorme"},"fr":{"text":"Il dort"},"en":{"text":"He sleeps"},"es":{"text":"Duerme"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Vai-se embora"},"fr":{"text":"Il s’en va"},"en":{"text":"He goes away"},"es":{"text":"Se va"}}}]}$json$::jsonb);
