select public.upsert_bank_question($json${"id":"cartas2-easy-025","type":"order","level":"easy","testament":"nt","book":"2PE","chapter":2,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Ordena estes acontecimentos, lembrados em 2 Pedro, pela ordem em que aconteceram.","bible_ref":"2 Pedro 2:5","verse_text":null},"fr":{"prompt":"Mets ces événements, rappelés dans 2 Pierre, dans l’ordre où ils se sont produits.","bible_ref":"2 Pierre 2:5","verse_text":null},"en":{"prompt":"Put these events, recalled in 2 Peter, in the order they happened.","bible_ref":"2 Peter 2:5","verse_text":null},"es":{"prompt":"Ordena estos sucesos, recordados en 2 Pedro, según ocurrieron.","bible_ref":"2 Pedro 2:5","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Deus traz o dilúvio e guarda Noé","ref":"2 Pedro 2:5"},"fr":{"text":"Dieu fait venir le déluge et sauve Noé","ref":"2 Pierre 2:5"},"en":{"text":"God brings the flood and saves Noah","ref":"2 Peter 2:5"},"es":{"text":"Dios trae el diluvio y guarda a Noé","ref":"2 Pedro 2:5"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sodoma e Gomorra são reduzidas a cinza","ref":"2 Pedro 2:6"},"fr":{"text":"Sodome et Gomorrhe sont réduites en cendres","ref":"2 Pierre 2:6"},"en":{"text":"Sodom and Gomorrha are turned into ashes","ref":"2 Peter 2:6"},"es":{"text":"Sodoma y Gomorra son tornadas en ceniza","ref":"2 Pedro 2:6"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um animal de carga fala e trava Balaão","ref":"2 Pedro 2:16"},"fr":{"text":"Une ânesse parle et arrête Balaam","ref":"2 Pierre 2:16"},"en":{"text":"A dumb ass speaks and rebukes Balaam","ref":"2 Peter 2:16"},"es":{"text":"Una bestia de carga habla y refrena a Balaam","ref":"2 Pedro 2:16"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pedro ouve a voz do céu no monte santo","ref":"2 Pedro 1:18"},"fr":{"text":"Pierre entend la voix du ciel sur la sainte montagne","ref":"2 Pierre 1:18"},"en":{"text":"Peter hear