select public.upsert_bank_question($json${"id":"cartas2-medium-001","type":"choice","level":"medium","testament":"nt","book":"ROM","chapter":1,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Em Romanos 1:16, de que diz Paulo que não se envergonha?","bible_ref":"Romanos 1:16","verse_text":"Porque não me envergonho do Evangelho de Cristo, pois é o poder de Deus para a salvação de todo aquele que crê, primeiramente do judeu, e também do grego."},"fr":{"prompt":"Dans Romains 1:16, de quoi Paul dit-il qu’il n’a point honte ?","bible_ref":"Romains 1:16","verse_text":"Car je n’ai point honte de l’Évangile: c’est une puissance de Dieu pour le salut de quiconque croit, du Juif premièrement, puis du Grec,"},"en":{"prompt":"In Romans 1:16, what does Paul say he is not ashamed of?","bible_ref":"Romans 1:16","verse_text":"For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek."},"es":{"prompt":"En Romanos 1:16, ¿de qué dice Pablo que no se avergüenza?","bible_ref":"Romanos 1:16","verse_text":"Porque no me avergüenzo del evangelio: porque es potencia de Dios para salud á todo aquel que cree; al Judío primeramente y también al Griego."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Do Evangelho"},"fr":{"text":"De l’Évangile"},"en":{"text":"The gospel"},"es":{"text":"Del evangelio"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Da sua riqueza"},"fr":{"text":"De sa richesse"},"en":{"text":"His riches"},"es":{"text":"De sus riquezas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Da sua sabedoria"},"fr":{"text":"De sa sagesse"},"en":{"text":"His wisdom"},"es":{"text":"De su sabiduría"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Da sua cidade natal"},"fr":{"text":"De sa ville natale"},"en":{"text":"His home town"},"es":{"text":"De su ciudad natal"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-002","type":"choice","level":"medium","testament":"nt","book":"ROM","chapter":5,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Romanos 5:8, quando morreu Cristo por nós?","bible_ref":"Romanos 5:8","verse_text":"Mas Deus prova o seu amor por nós através de Cristo haver morrido por nós, quando ainda éramos pecadores."},"fr":{"prompt":"Selon Romains 5:8, quand Christ est-il mort pour nous ?","bible_ref":"Romains 5:8","verse_text":"Mais Dieu prouve son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous."},"en":{"prompt":"According to Romans 5:8, when did Christ die for us?","bible_ref":"Romans 5:8","verse_text":"But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us."},"es":{"prompt":"Según Romanos 5:8, ¿cuándo murió Cristo por nosotros?","bible_ref":"Romanos 5:8","verse_text":"Mas Dios encarece su caridad para con nosotros, porque siendo aún pecadores, Cristo murió por nosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quando ainda éramos pecadores"},"fr":{"text":"Lorsque nous étions encore des pécheurs"},"en":{"text":"While we were yet sinners"},"es":{"text":"Siendo aún pecadores"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Depois de nos tornarmos justos"},"fr":{"text":"Après que nous sommes devenus justes"},"en":{"text":"After we became righteous"},"es":{"text":"Después de hacernos justos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quando guardámos toda a lei"},"fr":{"text":"Quand nous avons gardé toute la loi"},"en":{"text":"When we had kept all the law"},"es":{"text":"Cuando guardamos toda la ley"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quando lhe pedimos"},"fr":{"text":"Quand nous le lui avons demandé"},"en":{"text":"When we asked him to"},"es":{"text":"Cuando se lo pedimos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-003","type":"choice","level":"medium","testament":"nt","book":"ROM","chapter":12,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Romanos 12:1, como devemos apresentar os nossos corpos a Deus?","bible_ref":"Romanos 12:1","verse_text":"Rogo-vos, pois, irmãos, pelas misericórdias de Deus, que apresenteis os vossos corpos como sacrifício vivo, santo e agradável a Deus, que é o vosso culto racional."},"fr":{"prompt":"Selon Romains 12:1, comment devons-nous offrir nos corps à Dieu ?","bible_ref":"Romains 12:1","verse_text":"Je vous exhorte donc, frères, par les compassions de Dieu, à offrir vos corps comme un sacrifice vivant, saint, agréable à Dieu, ce qui sera de votre part un culte raisonnable."},"en":{"prompt":"According to Romans 12:1, how should we present our bodies to God?","bible_ref":"Romans 12:1","verse_text":"I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service."},"es":{"prompt":"Según Romanos 12:1, ¿cómo debemos presentar nuestros cuerpos a Dios?","bible_ref":"Romanos 12:1","verse_text":"Así que, hermanos, os ruego por las misericordias de Dios, que presentéis vuestros cuerpos en sacrificio vivo, santo, agradable á Dios, que es vuestro racional culto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Como sacrifício vivo"},"fr":{"text":"Comme un sacrifice vivant"},"en":{"text":"A living sacrifice"},"es":{"text":"En sacrificio vivo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Como oferta queimada"},"fr":{"text":"Comme un holocauste"},"en":{"text":"A burnt offering"},"es":{"text":"En holocausto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Como templo de pedra"},"fr":{"text":"Comme un temple de pierre"},"en":{"text":"A temple of stone"},"es":{"text":"Como templo de piedra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Como servos do rei"},"fr":{"text":"Comme serviteurs du roi"},"en":{"text":"As servants of the king"},"es":{"text":"Como siervos del rey"}}}]}$json$::jsonb);
