select public.upsert_bank_question($json${"id":"cartas2-medium-005","type":"choice","level":"medium","testament":"nt","book":"2CO","chapter":5,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Segundo 2 Coríntios 5:17, se alguém está em Cristo, o que é?","bible_ref":"2 Coríntios 5:17","verse_text":"Portanto, se alguém está em Cristo, uma nova criatura é; as coisas velhas já passaram, eis que tudo se fez novo."},"fr":{"prompt":"Selon 2 Corinthiens 5:17, si quelqu’un est en Christ, qu’est-il ?","bible_ref":"2 Corinthiens 5:17","verse_text":"Si quelqu’un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées; voici, toutes choses sont devenues nouvelles."},"en":{"prompt":"According to 2 Corinthians 5:17, if any man be in Christ, what is he?","bible_ref":"2 Corinthians 5:17","verse_text":"Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new."},"es":{"prompt":"Según 2 Corintios 5:17, si alguno está en Cristo, ¿qué es?","bible_ref":"2 Corintios 5:17","verse_text":"De modo que si alguno está en Cristo, nueva criatura es: las cosas viejas pasaron; he aquí todas son hechas nuevas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma nova criatura"},"fr":{"text":"Une nouvelle créature"},"en":{"text":"A new creature"},"es":{"text":"Nueva criatura"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um anjo"},"fr":{"text":"Un ange"},"en":{"text":"An angel"},"es":{"text":"Un ángel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um profeta"},"fr":{"text":"Un prophète"},"en":{"text":"A prophet"},"es":{"text":"Un profeta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um homem perfeito"},"fr":{"text":"Un homme parfait"},"en":{"text":"A perfect man"},"es":{"text":"Un hombre perfecto"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-006","type":"choice","level":"medium","testament":"nt","book":"EPH","chapter":4,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Segundo Efésios 4:26, o que não se deve pôr sobre a nossa ira?","bible_ref":"Efésios 4:26","verse_text":"Quando irardes, não pequeis; o sol não se ponha sobre a vossa ira;"},"fr":{"prompt":"Selon Éphésiens 4:26, qu’est-ce qui ne doit pas se coucher sur notre colère ?","bible_ref":"Éphésiens 4:26","verse_text":"Si vous vous mettez en colère, ne péchez point; que le soleil ne se couche pas sur votre colère,"},"en":{"prompt":"According to Ephesians 4:26, what should not go down upon our wrath?","bible_ref":"Ephesians 4:26","verse_text":"Be ye angry, and sin not: let not the sun go down upon your wrath:"},"es":{"prompt":"Según Efesios 4:26, ¿qué no debe ponerse sobre nuestro enojo?","bible_ref":"Efesios 4:26","verse_text":"Airaos, y no pequéis; no se ponga el sol sobre vuestro enojo;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O sol"},"fr":{"text":"Le soleil"},"en":{"text":"The sun"},"es":{"text":"El sol"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A lua"},"fr":{"text":"La lune"},"en":{"text":"The moon"},"es":{"text":"La luna"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As estrelas"},"fr":{"text":"Les étoiles"},"en":{"text":"The stars"},"es":{"text":"Las estrellas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A noite"},"fr":{"text":"La nuit"},"en":{"text":"The night"},"es":{"text":"La noche"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-007","type":"choice","level":"medium","testament":"nt","book":"EPH","chapter":6,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Segundo Efésios 6:16, com que podemos apagar as flechas inflamadas do maligno?","bible_ref":"Efésios 6:16","verse_text":"Sobretudo pegai o escudo da fé, com o qual podereis apagar todas as flechas inflamadas do maligno."},"fr":{"prompt":"Selon Éphésiens 6:16, avec quoi pouvons-nous éteindre les traits enflammés du malin ?","bible_ref":"Éphésiens 6:16","verse_text":"prenez par-dessus tout cela le bouclier de la foi, avec lequel vous pourrez éteindre tous les traits enflammés du malin;"},"en":{"prompt":"According to Ephesians 6:16, with what can we quench the fiery darts of the wicked?","bible_ref":"Ephesians 6:16","verse_text":"Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked."},"es":{"prompt":"Según Efesios 6:16, ¿con qué podemos apagar los dardos de fuego del maligno?","bible_ref":"Efesios 6:16","verse_text":"Sobre todo, tomando el escudo de la fe, con que podáis apagar todos los dardos de fuego del maligno."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com o escudo da fé"},"fr":{"text":"Avec le bouclier de la foi"},"en":{"text":"With the shield of faith"},"es":{"text":"Con el escudo de la fe"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com o capacete da salvação"},"fr":{"text":"Avec le casque du salut"},"en":{"text":"With the helmet of salvation"},"es":{"text":"Con el yelmo de la salud"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com a couraça da justiça"},"fr":{"text":"Avec la cuirasse de la justice"},"en":{"text":"With the breastplate of righteousness"},"es":{"text":"Con la cota de justicia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com a água do rio"},"fr":{"text":"Avec l’eau du fleuve"},"en":{"text":"With water from the river"},"es":{"text":"Con el agua del río"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-008","type":"choice","level":"medium","testament":"nt","book":"COL","chapter":3,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Colossenses 3:2, em que coisas devemos pensar?","bible_ref":"Colossenses 3:2","verse_text":"Pensai nas coisas de cima, não nas que estão na terra."},"fr":{"prompt":"Selon Colossiens 3:2, à quelles choses devons-nous nous affectionner ?","bible_ref":"Colossiens 3:2","verse_text":"Affectionnez-vous aux choses d’en haut, et non à celles qui sont sur la terre."},"en":{"prompt":"According to Colossians 3:2, on what things should we set our affection?","bible_ref":"Colossians 3:2","verse_text":"Set your affection on things above, not on things on the earth."},"es":{"prompt":"Según Colosenses 3:2, ¿en qué cosas debemos poner la mira?","bible_ref":"Colosenses 3:2","verse_text":"Poned la mira en las cosas de arriba, no en las de la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nas coisas de cima"},"fr":{"text":"Aux choses d’en haut"},"en":{"text":"On things above"},"es":{"text":"En las cosas de arriba"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nas coisas da terra"},"fr":{"text":"Aux choses de la terre"},"en":{"text":"On things on the earth"},"es":{"text":"En las cosas de la tierra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nas riquezas"},"fr":{"text":"Aux richesses"},"en":{"text":"On riches"},"es":{"text":"En las riquezas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nas coisas do passado"},"fr":{"text":"Aux choses du passé"},"en":{"text":"On things of the past"},"es":{"text":"En las cosas del pasado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-009","type":"choice","level":"medium","testament":"nt","book":"1TH","chapter":5,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo 1 Tessalonicenses 5:2, como virá o dia do Senhor?","bible_ref":"1 Tessalonicenses 5:2","verse_text":"pois vós mesmos bem sabeis que o dia do Senhor virá como um ladrão de noite."},"fr":{"prompt":"Selon 1 Thessaloniciens 5:2, comment viendra le jour du Seigneur ?","bible_ref":"1 Thessaloniciens 5:2","verse_text":"Car vous savez bien vous-mêmes que le jour du Seigneur viendra comme un voleur dans la nuit."},"en":{"prompt":"According to 1 Thessalonians 5:2, how cometh the day of the Lord?","bible_ref":"1 Thessalonians 5:2","verse_text":"For yourselves know perfectly that the day of the Lord so cometh as a thief in the night."},"es":{"prompt":"Según 1 Tesalonicenses 5:2, ¿cómo vendrá el día del Señor?","bible_ref":"1 Tesalonicenses 5:2","verse_text":"Porque vosotros sabéis bien, que el día del Señor vendrá así como ladrón de noche,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Como um ladrão de noite"},"fr":{"text":"Comme un voleur dans la nuit"},"en":{"text":"As a thief in the night"},"es":{"text":"Como ladrón de noche"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Como um rei anunciado com antecedência"},"fr":{"text":"Comme un roi annoncé à l’avance"},"en":{"text":"As a king announced in advance"},"es":{"text":"Como un rey anunciado de antemano"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Como a aurora de cada dia"},"fr":{"text":"Comme l’aurore de chaque jour"},"en":{"text":"As the dawn of every day"},"es":{"text":"Como la aurora de cada día"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Como um mensageiro em pleno dia"},"fr":{"text":"Comme un messager en plein jour"},"en":{"text":"As a messenger in broad daylight"},"es":{"text":"Como un mensajero a plena luz"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-010","type":"choice","level":"medium","testament":"nt","book":"2TH","chapter":3,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo 2 Tessalonicenses 3:13, de que não nos devemos cansar?","bible_ref":"2 Tessalonicenses 3:13","verse_text":"E vós, irmãos, não vos canseis de fazer o bem."},"fr":{"prompt":"Selon 2 Thessaloniciens 3:13, de quoi ne devons-nous pas nous lasser ?","bible_ref":"2 Thessaloniciens 3:13","verse_text":"Pour vous, frères, ne vous lassez pas de faire le bien."},"en":{"prompt":"According to 2 Thessalonians 3:13, in what should we not be weary?","bible_ref":"2 Thessalonians 3:13","verse_text":"But ye, brethren, be not weary in well doing."},"es":{"prompt":"Según 2 Tesalonicenses 3:13, ¿de qué no debemos cansarnos?","bible_ref":"2 Tesalonicenses 3:13","verse_text":"Y vosotros, hermanos, no os canséis de hacer bien."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De fazer o bem"},"fr":{"text":"De faire le bien"},"en":{"text":"In well doing"},"es":{"text":"De hacer bien"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De jejuar"},"fr":{"text":"De jeûner"},"en":{"text":"In fasting"},"es":{"text":"De ayunar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De cantar"},"fr":{"text":"De chanter"},"en":{"text":"In singing"},"es":{"text":"De cantar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De viajar"},"fr":{"text":"De voyager"},"en":{"text":"In travelling"},"es":{"text":"De viajar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-011","type":"choice","level":"medium","testament":"nt","book":"1TI","chapter":2,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo 1 Timóteo 2:5, quem é o único mediador entre Deus e os homens?","bible_ref":"1 Timóteo 2:5","verse_text":"Pois há um só Deus, e um só Mediador entre Deus e os seres humanos: o humano Cristo Jesus."},"fr":{"prompt":"Selon 1 Timothée 2:5, qui est le seul médiateur entre Dieu et les hommes ?","bible_ref":"1 Timothée 2:5","verse_text":"Car il y a un seul Dieu, et aussi un seul médiateur entre Dieu et les hommes, Jésus-Christ homme,"},"en":{"prompt":"According to 1 Timothy 2:5, who is the one mediator between God and men?","bible_ref":"1 Timothy 2:5","verse_text":"For there is one God, and one mediator between God and men, the man Christ Jesus;"},"es":{"prompt":"Según 1 Timoteo 2:5, ¿quién es el único mediador entre Dios y los hombres?","bible_ref":"1 Timoteo 2:5","verse_text":"Porque hay un Dios, asimismo un mediador entre Dios y los hombres, Jesucristo hombre;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cristo Jesus"},"fr":{"text":"Jésus-Christ"},"en":{"text":"Christ Jesus"},"es":{"text":"Jesucristo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O sumo sacerdote"},"fr":{"text":"Le souverain sacrificateur"},"en":{"text":"The high priest"},"es":{"text":"El sumo sacerdote"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os anjos"},"fr":{"text":"Les anges"},"en":{"text":"The angels"},"es":{"text":"Los ángeles"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-012","type":"choice","level":"medium","testament":"nt","book":"2TI","chapter":4,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Em 2 Timóteo 4:7, Paulo lutou a boa luta e terminou a carreira. O que guardou?","bible_ref":"2 Timóteo 4:7","verse_text":"Lutei a boa luta, terminei a carreira, guardei a fé."},"fr":{"prompt":"Dans 2 Timothée 4:7, Paul a combattu le bon combat et achevé la course. Qu’a-t-il gardé ?","bible_ref":"2 Timothée 4:7","verse_text":"J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi."},"en":{"prompt":"In 2 Timothy 4:7, Paul fought a good fight and finished his course. What did he keep?","bible_ref":"2 Timothy 4:7","verse_text":"I have fought a good fight, I have finished my course, I have kept the faith:"},"es":{"prompt":"En 2 Timoteo 4:7, Pablo peleó la buena batalla y acabó la carrera. ¿Qué guardó?","bible_ref":"2 Timoteo 4:7","verse_text":"He peleado la buena batalla, he acabado la carrera, he guardado la fe."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A fé"},"fr":{"text":"La foi"},"en":{"text":"The faith"},"es":{"text":"La fe"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O ouro"},"fr":{"text":"L’or"},"en":{"text":"The gold"},"es":{"text":"El oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A lei"},"fr":{"text":"La loi"},"en":{"text":"The law"},"es":{"text":"La ley"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O templo"},"fr":{"text":"Le temple"},"en":{"text":"The temple"},"es":{"text":"El templo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-013","type":"choice","level":"medium","testament":"nt","book":"TIT","chapter":3,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo Tito 3:5, segundo o que nos salvou Deus?","bible_ref":"Tito 3:5","verse_text":"Não pelas obras de justiça que nós tivéssemos feito, mas sim segundo sua misericórdia, ele nos salvou pelo banho do novo nascimento, e da renovação do Espírito Santo;"},"fr":{"prompt":"Selon Tite 3:5, selon quoi Dieu nous a-t-il sauvés ?","bible_ref":"Tite 3:5","verse_text":"il nous a sauvés, non à cause des œuvres de justice que nous aurions faites, mais selon sa miséricorde, par le baptême de la régénération et le renouvellement du Saint-Esprit,"},"en":{"prompt":"According to Titus 3:5, according to what did God save us?","bible_ref":"Titus 3:5","verse_text":"Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;"},"es":{"prompt":"Según Tito 3:5, ¿por qué medio nos salvó Dios?","bible_ref":"Tito 3:5","verse_text":"No por obras de justicia que nosotros habíamos hecho, mas por su misericordia nos salvó, por el lavacro de la regeneración, y de la renovación del Espíritu Santo;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Segundo a sua misericórdia"},"fr":{"text":"Selon sa miséricorde"},"en":{"text":"According to his mercy"},"es":{"text":"Por su misericordia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Segundo as nossas obras de justiça"},"fr":{"text":"Selon nos œuvres de justice"},"en":{"text":"According to our works of righteousness"},"es":{"text":"Por nuestras obras de justicia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Segundo a nossa riqueza"},"fr":{"text":"Selon notre richesse"},"en":{"text":"According to our riches"},"es":{"text":"Por nuestra riqueza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Segundo a nossa famí