select public.upsert_bank_question($json${"id":"cartas2-medium-014","type":"choice","level":"medium","testament":"nt","book":"PHM","chapter":1,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Em Filémon 1:16, Paulo diz que alguém deve ser recebido não mais como servo, mas como quê?","bible_ref":"Filémon 1:16","verse_text":"Não mais como a um servo, mas sim mais que um servo, como a um amado irmão, especialmente para mim, e muito mais de ti, tanto na carne como no Senhor."},"fr":{"prompt":"Dans Philémon 1:16, Paul dit que quelqu’un doit être reçu non plus comme un esclave, mais comme quoi ?","bible_ref":"Philémon 1:16","verse_text":"non plus comme un esclave, mais comme supérieur à un esclave, comme un frère bien-aimé, de moi particulièrement, et de toi à plus forte raison, soit dans la chair, soit dans le Seigneur."},"en":{"prompt":"In Philemon 1:16, Paul says someone should be received no longer as a servant, but as what?","bible_ref":"Philemon 1:16","verse_text":"Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord?"},"es":{"prompt":"En Filemón 1:16, Pablo dice que alguien debe ser recibido ya no como siervo, sino ¿como qué?","bible_ref":"Filemón 1:16","verse_text":"No ya como siervo, antes más que siervo, como hermano amado, mayormente de mí, pero cuánto más de ti, en la carne y en el Señor."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Como um irmão amado"},"fr":{"text":"Comme un frère bien-aimé"},"en":{"text":"As a brother beloved"},"es":{"text":"Como hermano amado"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Como um servo castigado"},"fr":{"text":"Comme un esclave puni"},"en":{"text":"As a punished servant"},"es":{"text":"Como siervo castigado"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Como um estranho"},"fr":{"text":"Comme un étranger"},"en":{"text":"As a stranger"},"es":{"text":"Como un extraño"}}},{"positio