select public.upsert_bank_question($json${"id":"cartas2-medium-015","type":"choice","level":"medium","testament":"nt","book":"HEB","chapter":4,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Hebreus 4:12, a palavra de Deus é mais afiada do que o quê?","bible_ref":"Hebreus 4:12","verse_text":"Porque a palavra de Deus é viva e eficaz, e mais afiada do que toda espada de dois gumes, e que penetra até a divisão da alma e do espírito, das juntas e das medulas, e é apta para julgar os pensamentos e intenções do coração."},"fr":{"prompt":"Selon Hébreux 4:12, la parole de Dieu est plus tranchante que quoi ?","bible_ref":"Hébreux 4:12","verse_text":"Car la parole de Dieu est vivante et efficace, plus tranchante qu’une épée quelconque à deux tranchants, pénétrante jusqu’à partager âme et esprit, jointures et mœlles; elle juge les sentiments et les pensées du cœur."},"en":{"prompt":"According to Hebrews 4:12, the word of God is sharper than what?","bible_ref":"Hebrews 4:12","verse_text":"For the word of God is quick, and powerful, and sharper than any twoedged sword, piercing even to the dividing asunder of soul and spirit, and of the joints and marrow, and is a discerner of the thoughts and intents of the heart."},"es":{"prompt":"Según Hebreos 4:12, la palabra de Dios es más penetrante que ¿qué?","bible_ref":"Hebreos 4:12","verse_text":"Porque la palabra de Dios es viva y eficaz, y más penetrante que toda espada de dos filos: y que alcanza hasta partir el alma, y aun el espíritu, y las coyunturas y tuétanos, y discierne los pensamientos y las intenciones del corazón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Toda a espada de dois gumes"},"fr":{"text":"Une épée quelconque à deux tranchants"},"en":{"text":"Any twoedged sword"},"es":{"text":"Toda espada de dos filos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma faca de pedra"},"fr":{"text":"Un couteau de pierre"},"en":{"text":"A knife of stone"},"es":{"text":"Un cuchillo de piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um machado de ferro"},"fr":{"text":"Une hache de fer"},"en":{"text":"An axe of iron"},"es":{"text":"Un hacha de hierro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A ponta de uma lança"},"fr":{"text":"La pointe d’une lance"},"en":{"text":"The point of a spear"},"es":{"text":"La punta de una lanza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-016","type":"choice","level":"medium","testament":"nt","book":"HEB","chapter":12,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Hebreus 12:1, de que estamos rodeados?","bible_ref":"Hebreus 12:1","verse_text":"Portanto nós também, posto que estamos rodeados por uma tão grande nuvem de testemunhas, deixemos toda sobrecarga, e o pecado que facilmente nos envolve, e corramos com perseverança a corrida que nos está proposta,"},"fr":{"prompt":"Selon Hébreux 12:1, de quoi sommes-nous environnés ?","bible_ref":"Hébreux 12:1","verse_text":"Nous donc aussi, puisque nous sommes environnés d’une si grande nuée de témoins, rejetons tout fardeau, et le péché qui nous enveloppe si facilement, et courons avec persévérance dans la carrière qui nous est ouverte,"},"en":{"prompt":"According to Hebrews 12:1, with what are we compassed about?","bible_ref":"Hebrews 12:1","verse_text":"Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,"},"es":{"prompt":"Según Hebreos 12:1, ¿de qué estamos rodeados?","bible_ref":"Hebreos 12:1","verse_text":"Por tanto nosotros también, teniendo en derredor nuestro una tan grande nube de testigos, dejando todo el peso del pecado que nos rodea, corramos con paciencia la carrera que nos es propuesta,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De uma grande nuvem de testemunhas"},"fr":{"text":"D’une grande nuée de témoins"},"en":{"text":"A great cloud of witnesses"},"es":{"text":"De una grande nube de testigos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De um grande exército de anjos"},"fr":{"text":"D’une grande armée d’anges"},"en":{"text":"A great army of angels"},"es":{"text":"De un grande ejército de ángeles"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De uma grande muralha de pedra"},"fr":{"text":"D’une grande muraille de pierre"},"en":{"text":"A great wall of stone"},"es":{"text":"De un grande muro de piedra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De uma grande família de reis"},"fr":{"text":"D’une grande famille de rois"},"en":{"text":"A great family of kings"},"es":{"text":"De una grande familia de reyes"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-017","type":"choice","level":"medium","testament":"nt","book":"JAS","chapter":2,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Segundo Tiago 2:26, como está a fé sem obras?","bible_ref":"Tiago 2:26","verse_text":"Pois assim como o corpo sem o espírito está morto, assim também a fé sem obras está morta."},"fr":{"prompt":"Selon Jacques 2:26, comment est la foi sans les œuvres ?","bible_ref":"Jacques 2:26","verse_text":"Comme le corps sans âme est mort, de même la foi sans les œuvres est morte."},"en":{"prompt":"According to James 2:26, what is faith without works?","bible_ref":"James 2:26","verse_text":"For as the body without the spirit is dead, so faith without works is dead also."},"es":{"prompt":"Según Santiago 2:26, ¿cómo es la fe sin obras?","bible_ref":"Santiago 2:26","verse_text":"Porque como el cuerpo sin espíritu está muerto, así también la fe sin obras es muerta."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Morta"},"fr":{"text":"Morte"},"en":{"text":"Dead"},"es":{"text":"Muerta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Forte"},"fr":{"text":"Forte"},"en":{"text":"Strong"},"es":{"text":"Fuerte"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Perfeita"},"fr":{"text":"Parfaite"},"en":{"text":"Perfect"},"es":{"text":"Perfecta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Escondida"},"fr":{"text":"Cachée"},"en":{"text":"Hidden"},"es":{"text":"Escondida"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-018","type":"choice","level":"medium","testament":"nt","book":"1PE","chapter":2,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo 1 Pedro 2:9, os crentes são que tipo de sacerdócio?","bible_ref":"1 Pedro 2:9","verse_text":"Mas vós sois a geração escolhida, o sacerdócio real, a nação santa, o povo adquirido; a fim de que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz."},"fr":{"prompt":"Selon 1 Pierre 2:9, quel sacerdoce sont les croyants ?","bible_ref":"1 Pierre 2:9","verse_text":"Vous, au contraire, vous êtes une race élue, un sacerdoce royal, une nation sainte, un peuple acquis, afin que vous annonciez les vertus de celui qui vous a appelés des ténèbres à son admirable lumière,"},"en":{"prompt":"According to 1 Peter 2:9, what kind of priesthood are believers?","bible_ref":"1 Peter 2:9","verse_text":"But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:"},"es":{"prompt":"Según 1 Pedro 2:9, ¿qué sacerdocio son los creyentes?","bible_ref":"1 Pedro 2:9","verse_text":"Mas vosotros sois linaje escogido, real sacerdocio, gente santa, pueblo adquirido, para que anunciéis las virtudes de aquel que os ha llamado de las tinieblas á su luz admirable:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um sacerdócio real"},"fr":{"text":"Un sacerdoce royal"},"en":{"text":"A royal priesthood"},"es":{"text":"Real sacerdocio"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um sacerdócio levítico"},"fr":{"text":"Un sacerdoce lévitique"},"en":{"text":"A Levitical priesthood"},"es":{"text":"Un sacerdocio levítico"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um sacerdócio terreno"},"fr":{"text":"Un sacerdoce terrestre"},"en":{"text":"An earthly priesthood"},"es":{"text":"Un sacerdocio terrenal"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um sacerdócio passageiro"},"fr":{"text":"Un sacerdoce passager"},"en":{"text":"A passing priesthood"},"es":{"text":"Un sacerdocio pasajero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-019","type":"choice","level":"medium","testament":"nt","book":"2PE","chapter":1,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Segundo 2 Pedro 1:21, movidos por quem falaram os santos homens de Deus?","bible_ref":"2 Pedro 1:21","verse_text":"Porque a profecia jamais foi produzida pela vontade humana, mas os santos homens de Deus falaram conduzidos pelo Espírito Santo."},"fr":{"prompt":"Selon 2 Pierre 1:21, poussés par qui des hommes ont-ils parlé de la part de Dieu ?","bible_ref":"2 Pierre 1:21","verse_text":"car ce n’est pas par une volonté d’homme qu’une prophétie a jamais été apportée, mais c’est poussés par le Saint-Esprit que des hommes ont parlé de la part de Dieu."},"en":{"prompt":"According to 2 Peter 1:21, by whom were holy men of God moved when they spake?","bible_ref":"2 Peter 1:21","verse_text":"For the prophecy came not in old time by the will of man: but holy men of God spake as they were moved by the Holy Ghost."},"es":{"prompt":"Según 2 Pedro 1:21, ¿inspirados por quién hablaron los santos hombres de Dios?","bible_ref":"2 Pedro 1:21","verse_text":"Porque la profecía no fué en los tiempos pasados traída por voluntad humana, sino los santos hombres de Dios hablaron siendo inspirados del Espíritu Santo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Pelo Espírito Santo"},"fr":{"text":"Par le Saint-Esprit"},"en":{"text":"By the Holy Ghost"},"es":{"text":"Por el Espíritu Santo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pela vontade humana"},"fr":{"text":"Par une volonté d’homme"},"en":{"text":"By the will of man"},"es":{"text":"Por voluntad humana"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pelos reis de Israel"},"fr":{"text":"Par les rois d’Israël"},"en":{"text":"By the kings of Israel"},"es":{"text":"Por los reyes de Israel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pelos sábios da Grécia"},"fr":{"text":"Par le