select public.upsert_bank_question($json${"id":"cartas2-medium-020","type":"choice","level":"medium","testament":"nt","book":"2JN","chapter":1,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo 2 João 1:10, o que não se deve fazer a quem não traz esta doutrina?","bible_ref":"2 João 1:10","verse_text":"Se alguém vem a vós, e não traz esta doutrina, não recebais em vossa casa, nem o saudeis."},"fr":{"prompt":"Selon 2 Jean 1:10, que ne faut-il pas faire à celui qui n’apporte pas cette doctrine ?","bible_ref":"2 Jean 1:10","verse_text":"Si quelqu’un vient à vous et n’apporte pas cette doctrine, ne le recevez pas dans votre maison, et ne lui dites pas: Salut!"},"en":{"prompt":"According to 2 John 1:10, what should you not do to one who brings not this doctrine?","bible_ref":"2 John 1:10","verse_text":"If there come any unto you, and bring not this doctrine, receive him not into your house, neither bid him God speed:"},"es":{"prompt":"Según 2 Juan 1:10, ¿qué no se debe hacer con quien no trae esta doctrina?","bible_ref":"2 Juan 1:10","verse_text":"Si alguno viene á vosotros, y no trae esta doctrina, no lo recibáis en casa, ni le digáis: ¡bienvenido!"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Recebê-lo em casa"},"fr":{"text":"Le recevoir dans sa maison"},"en":{"text":"Receive him into your house"},"es":{"text":"Recibirlo en casa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Orar por ele"},"fr":{"text":"Prier pour lui"},"en":{"text":"Pray for him"},"es":{"text":"Orar por él"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Escrever-lhe uma carta"},"fr":{"text":"Lui écrire une lettre"},"en":{"text":"Write him a letter"},"es":{"text":"Escribirle una carta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dar-lhe um conselho"},"fr":{"text":"Lui donner un conseil"},"en":{"text":"Give him advice"},"es":{"text":"Darle un consejo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-medium-021","type":"choice","level":"medium","testament":"nt","book":"JUD","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Judas 1:3, pelo que devemos batalhar?","bible_ref":"Judas 1:3","verse_text":"Amados, procurando eu vos escrever com todo empenho sobre a nossa salvação comum, eu tive por necessário vos escrever e exortar a batalhar pela fé que de uma vez foi entregue aos santos."},"fr":{"prompt":"Selon Jude 1:3, pour quoi devons-nous combattre ?","bible_ref":"Jude 1:3","verse_text":"Bien-aimés, comme je désirais vivement vous écrire au sujet de notre salut commun, je me suis senti obligé de le faire afin de vous exhorter à combattre pour la foi qui a été transmise aux saints une fois pour toutes."},"en":{"prompt":"According to Jude 1:3, for what should we earnestly contend?","bible_ref":"Jude 1:3","verse_text":"Beloved, when I gave all diligence to write unto you of the common salvation, it was needful for me to write unto you, and exhort you that ye should earnestly contend for the faith which was once delivered unto the saints."},"es":{"prompt":"Según Judas 1:3, ¿por qué debemos contender eficazmente?","bible_ref":"Judas 1:3","verse_text":"Amados, por la gran solicitud que tenía de escribiros de la común salud, me ha sido necesario escribiros amonestándoos que contendáis eficazmente por la fe que ha sido una vez dada á los santos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Pela fé entregue aos santos"},"fr":{"text":"Pour la foi transmise aux saints"},"en":{"text":"For the faith delivered unto the saints"},"es":{"text":"Por la fe dada a los santos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pela terra prometida"},"fr":{"text":"Pour la terre promise"},"en":{"text":"For the promised land"},"es":{"text":"Por la tierra prometida"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pelo templo de Jerusalém"},"fr":{"text":"Pour le temple de Jérusalem"},"en":{"text":"For the temple of Jerusalem"},"es":{"text":"Por el templo de Jerusalem"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pelas riquezas do mundo"},"fr":{"text":"Pour les richesses du monde"},"en":{"text":"For the riches of the world"},"es":{"text":"Por las riquezas del mundo"}}}]}$json$::jsonb);
