select public.upsert_bank_question($json${"id":"cartas2-hard-005","type":"choice","level":"hard","testament":"nt","book":"GAL","chapter":3,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Segundo Gálatas 3:17, quantos anos depois da promessa veio a Lei?","bible_ref":"Gálatas 3:17","verse_text":"Mas digo isto: o pacto foi confirmado anteriormente por Deus em Cristo; e a Lei que veio quatrocentos e trinta anos depois não o invalida de maneira que anule a promessa."},"fr":{"prompt":"Selon Galates 3:17, combien d’années après la promesse la loi est-elle survenue ?","bible_ref":"Galates 3:17","verse_text":"Voici ce que j’entends: une disposition, que Dieu a confirmée antérieurement, ne peut pas être annulée, et ainsi la promesse rendue vaine, par la loi survenue quatre cent trente ans plus tard."},"en":{"prompt":"According to Galatians 3:17, how many years after the promise came the law?","bible_ref":"Galatians 3:17","verse_text":"And this I say, that the covenant, that was confirmed before of God in Christ, the law, which was four hundred and thirty years after, cannot disannul, that it should make the promise of none effect."},"es":{"prompt":"Según Gálatas 3:17, ¿cuántos años después de la promesa fue hecha la ley?","bible_ref":"Gálatas 3:17","verse_text":"Esto pues digo: Que el contrato confirmado de Dios para con Cristo, la ley que fué hecha cuatrocientos treinta años después, no lo abroga, para invalidar la promesa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quatrocentos e trinta"},"fr":{"text":"Quatre cent trente"},"en":{"text":"Four hundred and thirty"},"es":{"text":"Cuatrocientos treinta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quarenta"},"fr":{"text":"Quarante"},"en":{"text":"Forty"},"es":{"text":"Cuarenta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Setenta"},"fr":{"text":"Soixante-dix"},"en":{"text":"Seventy"},"es":{"text":"Setenta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cento e vinte"},"fr":{"text":"Cent vingt"},"en":{"text":"A hundred and twenty"},"es":{"text":"Ciento veinte"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-006","type":"choice","level":"hard","testament":"nt","book":"EPH","chapter":6,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Segundo Efésios 6:21, quem iria contar aos efésios tudo sobre Paulo?","bible_ref":"Efésios 6:21","verse_text":"Para que também vós possais saber o que acontece comigo, e o que eu faço, Tíquico, o irmão amado, e fiel servidor do Senhor vos informará de tudo."},"fr":{"prompt":"Selon Éphésiens 6:21, qui devait informer les Éphésiens de tout ce qui concernait Paul ?","bible_ref":"Éphésiens 6:21","verse_text":"Afin que vous aussi, vous sachiez ce qui me concerne, ce que je fais, Tychique, le bien-aimé frère et fidèle ministre dans le Seigneur, vous informera de tout."},"en":{"prompt":"According to Ephesians 6:21, who would make known to the Ephesians all things about Paul?","bible_ref":"Ephesians 6:21","verse_text":"But that ye also may know my affairs, and how I do, Tychicus, a beloved brother and faithful minister in the Lord, shall make known to you all things:"},"es":{"prompt":"Según Efesios 6:21, ¿quién haría saber a los efesios todo acerca de Pablo?","bible_ref":"Efesios 6:21","verse_text":"Mas para que también vosotros sepáis mis negocios, y cómo lo paso, todo os lo hará saber Tichîco, hermano amado y fiel ministro en el Señor:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tíquico"},"fr":{"text":"Tychique"},"en":{"text":"Tychicus"},"es":{"text":"Tichîco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Onésimo"},"fr":{"text":"Onésime"},"en":{"text":"Onesimus"},"es":{"text":"Onésimo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Epafrodito"},"fr":{"text":"Épaphrodite"},"en":{"text":"Epaphroditus"},"es":{"text":"Epafrodito"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tito"},"fr":{"text":"Tite"},"en":{"text":"Titus"},"es":{"text":"Tito"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-007","type":"choice","level":"hard","testament":"nt","book":"PHP","chapter":4,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Em Filipenses 4:2, que duas mulheres exorta Paulo a terem o mesmo sentimento no Senhor?","bible_ref":"Filipenses 4:2","verse_text":"Rogo a Evódia e rogo a Síntique que tenham uma mesma mentalidade no Senhor."},"fr":{"prompt":"Dans Philippiens 4:2, quelles deux femmes Paul exhorte-t-il à être d’un même sentiment dans le Seigneur ?","bible_ref":"Philippiens 4:2","verse_text":"J’exhorte Évodie et j’exhorte Syntyche à être d’un même sentiment dans le Seigneur."},"en":{"prompt":"In Philippians 4:2, which two women does Paul beseech to be of the same mind in the Lord?","bible_ref":"Philippians 4:2","verse_text":"I beseech Euodias, and beseech Syntyche, that they be of the same mind in the Lord."},"es":{"prompt":"En Filipenses 4:2, ¿a qué dos mujeres ruega Pablo que sientan lo mismo en el Señor?","bible_ref":"Filipenses 4:2","verse_text":"A Euodias ruego, y á Syntychê exhorto, que sientan lo mismo en el Señor."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Evódia e Síntique"},"fr":{"text":"Évodie et Syntyche"},"en":{"text":"Euodias and Syntyche"},"es":{"text":"Euodias y Syntychê"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Lóide e Eunice"},"fr":{"text":"Loïs et Eunice"},"en":{"text":"Lois and Eunice"},"es":{"text":"Loida y Eunice"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Marta e Maria"},"fr":{"text":"Marthe et Marie"},"en":{"text":"Martha and Mary"},"es":{"text":"Marta y María"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lídia e Febe"},"fr":{"text":"Lydie et Phœbé"},"en":{"text":"Lydia and Phebe"},"es":{"text":"Lidia y Febe"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-008","type":"choice","level":"hard","testament":"nt","book":"COL","chapter":4,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Segundo Colossenses 4:16, que outra carta deviam ler os colossenses?","bible_ref":"Colossenses 4:16","verse_text":"E depois que esta carta for lida entre vós, fazei que ela também seja lida na igreja dos laodicenses, e que vós leiais também a de Laodiceia."},"fr":{"prompt":"Selon Colossiens 4:16, quelle autre lettre les Colossiens devaient-ils lire ?","bible_ref":"Colossiens 4:16","verse_text":"Lorsque cette lettre aura été lue chez vous, faites en sorte qu’elle soit aussi lue dans l’Église des Laodicéens, et que vous lisiez à votre tour celle qui vous arrivera de Laodicée."},"en":{"prompt":"According to Colossians 4:16, which other epistle were the Colossians to read?","bible_ref":"Colossians 4:16","verse_text":"And when this epistle is read among you, cause that it be read also in the church of the Laodiceans; and that ye likewise read the epistle from Laodicea."},"es":{"prompt":"Según Colosenses 4:16, ¿qué otra carta debían leer los colosenses?","bible_ref":"Colosenses 4:16","verse_text":"Y cuando esta carta fuere leída entre vosotros, haced que también sea leída en la iglesia de los Laodicenses; y la de Laodicea que la leáis también vosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A de Laodiceia"},"fr":{"text":"Celle de Laodicée"},"en":{"text":"The epistle from Laodicea"},"es":{"text":"La de Laodicea"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A de Éfeso"},"fr":{"text":"Celle d’Éphèse"},"en":{"text":"The epistle from Ephesus"},"es":{"text":"La de Efeso"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A de Filipos"},"fr":{"text":"Celle de Philippes"},"en":{"text":"The epistle from Philippi"},"es":{"text":"La de Filipos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A de Tessalónica"},"fr":{"text":"Celle de Thessalonique"},"en":{"text":"The epistle from Thessalonica"},"es":{"text":"La de Tesalónica"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-009","type":"choice","level":"hard","testament":"nt","book":"1TH","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo 1 Tessalonicenses 1:1, além de Timóteo, quem envia a carta com Paulo?","bible_ref":"1 Tessalonicenses 1:1","verse_text":"Paulo, Silvano, e Timóteo, à igreja dos tessalonicenses, em Deus Pai, e no Senhor Jesus Cristo; haja convosco a graça e a paz de Deus, nosso Pai, e do Senhor Jesus Cristo."},"fr":{"prompt":"Selon 1 Thessaloniciens 1:1, outre Timothée, qui envoie la lettre avec Paul ?","bible_ref":"1 Thessaloniciens 1:1","verse_text":"Paul, et Silvain, et Timothée, à l’Église des Thessaloniciens, qui est en Dieu le Père et en Jésus-Christ le Seigneur: que la grâce et la paix vous soient données!"},"en":{"prompt":"According to 1 Thessalonians 1:1, besides Timotheus, who sends the epistle with Paul?","bible_ref":"1 Thessalonians 1:1","verse_text":"Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians which is in God the Father and in the Lord Jesus Christ: Grace be unto you, and peace, from God our Father, and the Lord Jesus Christ."},"es":{"prompt":"Según 1 Tesalonicenses 1:1, además de Timoteo, ¿quién envía la carta con Pablo?","bible_ref":"1 Tesalonicenses 1:1","verse_text":"Pablo, y Silvano, y Timoteo, á la iglesia de los Tesalonicenses que es en Dios Padre y en el Señor Jesucristo: Gracia y paz á vosotros de Dios nuestro Padre y del Señor Jesucristo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Silvano"},"fr":{"text":"Silvain"},"en":{"text":"Silvanus"},"es":{"text":"Silvano"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Barnabé"},"fr":{"text":"Barnabas"},"en":{"text":"Barnabas"},"es":{"text":"Bernabé"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tito"},"fr":{"text":"Tite"},"en":{"text":"Titus"},"es":{"text":"Tito"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lucas"},"fr":{"text":"Luc"},"en":{"text":"Luke"},"es":{"text":"Lucas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-010","type":"choice","level":"hard","testament":"nt","book":"2TH","chapter":3,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Segundo 2 Tessalonicenses 3:17, qual era a assinatura de Paulo em todas as suas cartas?","bible_ref":"2 Tessalonicenses 3:17","verse_text":"A saudação de minha própria mão, Paulo, que é minha assinatura em toda carta; assim escrevo."},"fr":{"prompt":"Selon 2 Thessaloniciens 3:17, quelle était la signature de Paul dans toutes ses lettres ?","bible_ref":"2 Thessaloniciens 3:17","verse_text":"Je vous salue, moi Paul, de ma propre main. C’est là ma signature dans toutes mes lettres; c’est ainsi que j’écris."},"en":{"prompt":"According to 2 Thessalonians 3:17, what was Paul’s token in every epistle?","bible_ref":"2 Thessalonians 3:17","verse_text":"The salutation of Paul with mine own hand, which is the token in every epistle: so I write."},"es":{"prompt":"Según 2 Tesalonicenses 3:17, ¿cuál era el signo de Pablo en toda carta suya?","bible_ref":"2 Tesalonicenses 3:17","verse_text":"Salud de mi mano, Pablo, que es mi signo en toda carta mía: así escribo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A saudação da sua própria mão"},"fr":{"text":"La salutation de sa propre main"},"en":{"text":"The salutation with his own hand"},"es":{"text":"La salutación de su mano"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um selo de cera"},"fr":{"text":"Un sceau de cire"},"en":{"text":"A seal of wax"},"es":{"text":"Un sello de cera"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O nome de Timóteo"},"fr":{"text":"Le nom de Timothée"},"en":{"text":"The name of Timotheus"},"es":{"text":"El nombre de Timoteo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O desenho de um peixe"},"fr":{"text":"Le dessin d’un poisson"},"en":{"text":"The drawing of a fish"},"es":{"text":"El dibujo de un pez"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-011","type":"choice","level":"hard","testament":"nt","book":"2TH","chapter":2,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo 2 Tessalonicenses 2:3, o que tem de vir primeiro, antes desse dia?","bible_ref":"2 Tessalonicenses 2:3","verse_text":"Ninguém vos engane em maneira nenhuma; porque não virá esse dia sem que primeiro venha a apostasia, e se manifeste o homem do pecado, o filho da perdição."},"fr":{"prompt":"Selon 2 Thessaloniciens 2:3, que doit-il arriver auparavant, avant ce jour-là ?","bible_ref":"2 Thessaloniciens 2:3","verse_text":"Que personne ne vous séduise d’aucune manière; car il faut que l’apostasie soit arrivée auparavant, et qu’on ait vu paraître l’homme du péché, le fils de la perdition,"},"en":{"prompt":"According to 2 Thessalonians 2:3, what must come first, before that day?","bible_ref":"2 Thessalonians 2:3","verse_text":"Let no man deceive you by any means: for that day shall not come, except there come a falling away first, and that man of sin be revealed, the son of perdition;"},"es":{"prompt":"Según 2 Tesalonicenses 2:3, ¿qué debe venir antes de ese día?","bible_ref":"2 Tesalonicenses 2:3","verse_text":"No os engañe nadie en ninguna manera; porque no vendrá sin que venga antes la apostasía, y se manifieste el hombre de pecado, el hijo de perdición,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A apostasia"},"fr":{"text":"L’apostasie"},"en":{"text":"A falling away"},"es":{"text":"La apostasía"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma grande fome"},"fr":{"text":"Une grande famine"},"en":{"text":"A great famine"},"es":{"text":"Una grande hambre"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A reconstrução do templo"},"fr":{"text":"La reconstruction du temple"},"en":{"text":"The rebuilding of the temple"},"es":{"text":"La reconstrucción del templo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um eclipse do sol"},"fr":{"text":"Une éclipse de soleil"},"en":{"text":"An eclipse of the sun"},"es":{"text":"Un eclipse de sol"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-012","type":"choice","level":"hard","testament":"nt","book":"2TI","chapter":4,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo 2 Timóteo 4:10, quem abandonou Paulo por amor ao mundo presente?","bible_ref":"2 Timóteo 4:10","verse_text":"porque Demas me desamparou: ele amou o tempo presente, e partiu para Tessalônica; Crescente para a Galácia, e Tito para a Dalmácia."},"fr":{"prompt":"Selon 2 Timothée 4:10, qui a abandonné Paul par amour pour le siècle présent ?","bible_ref":"2 Timothée 4:10","verse_text":"car Démas m’a abandonné, par amour pour le siècle présent, et il est parti pour Thessalonique; Crescens est allé en Galatie, Tite en Dalmatie."},"en":{"prompt":"According to 2 Timothy 4:10, who forsook Paul, having loved this present world?","bible_ref":"2 Timothy 4:10","verse_text":"For Demas hath forsaken me, having loved this present world, and is departed unto Thessalonica; Crescens to Galatia, Titus unto Dalmatia."},"es":{"prompt":"Según 2 Timoteo 4:10, ¿quién desamparó a Pablo, amando este siglo?","bible_ref":"2 Timoteo 4:10","verse_text":"Porque Demas me ha desamparado, amando este siglo, y se ha ido á Tesalónica; Crescente á Galacia, Tito á Dalmacia."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Demas"},"fr":{"text":"Démas"},"en":{"text":"Demas"},"es":{"text":"Demas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Lucas"},"fr":{"text":"Luc"},"en":{"text":"Luke"},"es":{"text":"Lucas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Marcos"},"fr":{"text":"Marc"},"en":{"text":"Mark"},"es":{"text":"Marcos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Onesíforo"},"fr":{"text":"Onésiphore"},"en":{"text":"Onesiphorus"},"es":{"text":"Onesíforo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-013","type":"choice","level":"hard","testament":"nt","book":"TIT","chapter":3,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Tito 3:12, onde decidiu Paulo passar o inverno?","bible_ref":"Tito 3:12","verse_text":"Quando eu enviar Artemas até ti, ou Tíquico, procura vir até mim a Nicópolis, porque eu decidi passar lá o inverno."},"fr":{"prompt":"Selon Tite 3:12, où Paul avait-il résolu de passer l’hiver ?","bible_ref":"Tite 3:12","verse_text":"Lorsque je t’enverrai Artémas ou Tychique, hâte-toi de venir me rejoindre à Nicopolis; car c’est là que j’ai résolu de passer l’hiver."},"en":{"prompt":"According to Titus 3:12, where had Paul determined to winter?","bible_ref":"Titus 3:12","verse_text":"When I shall send Artemas unto thee, or Tychicus, be diligent to come unto me to Nicopolis: for I have determined there to winter."},"es":{"prompt":"Según Tito 3:12, ¿dónde había determinado Pablo invernar?","bible_ref":"Tito 3:12","verse_text":"Cuando enviare á ti á Artemas, ó á Tichîco, procura venir á mí, á Nicópolis: porque allí he determinado invernar."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em Nicópolis"},"fr":{"text":"À Nicopolis"},"en":{"text":"At Nicopolis"},"es":{"text":"En Nicópolis"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em Corinto"},"fr":{"text":"À Corinthe"},"en":{"text":"At Corinth"},"es":{"text":"En Corinto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Em Éfeso"},"fr":{"text":"À Éphèse"},"en":{"text":"At Ephesus"},"es":{"text":"En Efeso"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Em Atenas"},"fr":{"text":"À Athènes"},"en":{"text":"At Athens"},"es":{"text":"En Atenas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-014","type":"choice","level":"hard","testament":"nt","book":"PHM","chapter":1,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Segundo Filémon 1:22, o que pede Paulo que lhe preparem?","bible_ref":"Filémon 1:22","verse_text":"E enquanto isso também me prepara um lugar para eu ficar; porque eu espero que por vossas orações eu seja entregue a vós."},"fr":{"prompt":"Selon Philémon 1:22, que demande Paul qu’on lui prépare ?","bible_ref":"Philémon 1:22","verse_text":"En même temps, prépare-moi un logement, car j’espère vous être rendu, grâce à vos prières."},"en":{"prompt":"According to Philemon 1:22, what does Paul ask to be prepared for him?","bible_ref":"Philemon 1:22","verse_text":"But withal prepare me also a lodging: for I trust that through your prayers I shall be given unto you."},"es":{"prompt":"Según Filemón 1:22, ¿qué pide Pablo que le preparen?","bible_ref":"Filemón 1:22","verse_text":"Y asimismo prepárame también alojamiento; porque espero que por vuestras oraciones os tengo de ser concedido."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um lugar para ficar"},"fr":{"text":"Un logement"},"en":{"text":"A lodging"},"es":{"text":"Alojamiento"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um barco para a viagem"},"fr":{"text":"Un bateau pour le voyage"},"en":{"text":"A ship for the journey"},"es":{"text":"Un barco para el viaje"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um banquete"},"fr":{"text":"Un festin"},"en":{"text":"A feast"},"es":{"text":"Un banquete"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma carta para a igreja"},"fr":{"text":"Une lettre pour l’Église"},"en":{"text":"A letter for the church"},"es":{"text":"Una carta para la iglesia"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-015","type":"choice","level":"hard","testament":"nt","book":"HEB","chapter":7,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Hebreus 7:1, quem era rei de Salém e sacerdote do Deus Altíssimo e abençoou Abraão?","bible_ref":"Hebreus 7:1","verse_text":"Porque este Melquisedeque, rei de Salém, sacerdote do Deus Altíssimo, o qual se encontrou com Abraão, que estava retornando da matança dos reis, e o abençoou;"},"fr":{"prompt":"Selon Hébreux 7:1, qui était roi de Salem, sacrificateur du Dieu Très-Haut, et bénit Abraham ?","bible_ref":"Hébreux 7:1","verse_text":"En effet, ce Melchisédek, roi de Salem, sacrificateur du Dieu Très-Haut, qui alla au-devant d’Abraham lorsqu’il revenait de la défaite des rois, qui le bénit,"},"en":{"prompt":"According to Hebrews 7:1, who was king of Salem, priest of the most high God, and blessed Abraham?","bible_ref":"Hebrews 7:1","verse_text":"For this Melchisedec, king of Salem, priest of the most high God, who met Abraham returning from the slaughter of the kings, and blessed him;"},"es":{"prompt":"Según Hebreos 7:1, ¿quién era rey de Salem, sacerdote del Dios Altísimo, y bendijo a Abraham?","bible_ref":"Hebreos 7:1","verse_text":"Porque este Melchîsedec, rey de Salem, sacerdote del Dios Altísimo, el cual salió á recibir á Abraham que volvía de la derrota de los reyes, y le bendijo,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Melquisedeque"},"fr":{"text":"Melchisédek"},"en":{"text":"Melchisedec"},"es":{"text":"Melchîsedec"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Abimeleque"},"fr":{"text":"Abimélec"},"en":{"text":"Abimelech"},"es":{"text":"Abimelech"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ló"},"fr":{"text":"Lot"},"en":{"text":"Lot"},"es":{"text":"Lot"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Faraó"},"fr":{"text":"Pharaon"},"en":{"text":"Pharaoh"},"es":{"text":"Faraón"}}}]}$json$::jsonb