select public.upsert_bank_question($json${"id":"cartas2-hard-016","type":"choice","level":"hard","testament":"nt","book":"HEB","chapter":9,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Hebreus 9:4, de quem era a vara que florescera, guardada na arca?","bible_ref":"Hebreus 9:4","verse_text":"que tinha o incensário de ouro, e a arca do pacto, toda coberta de ouro. Nela estavam: o vaso de ouro contendo o maná, a vara de Arão que florescera, e as tábuas do pacto."},"fr":{"prompt":"Selon Hébreux 9:4, à qui était la verge qui avait fleuri, gardée dans l’arche ?","bible_ref":"Hébreux 9:4","verse_text":"renfermant l’autel d’or pour les parfums, et l’arche de l’alliance, entièrement recouverte d’or. Il y avait dans l’arche un vase d’or contenant la manne, la verge d’Aaron, qui avait fleuri, et les tables de l’alliance."},"en":{"prompt":"According to Hebrews 9:4, whose rod that budded was kept in the ark?","bible_ref":"Hebrews 9:4","verse_text":"Which had the golden censer, and the ark of the covenant overlaid round about with gold, wherein was the golden pot that had manna, and Aaron’s rod that budded, and the tables of the covenant;"},"es":{"prompt":"Según Hebreos 9:4, ¿de quién era la vara que reverdeció, guardada en el arca?","bible_ref":"Hebreos 9:4","verse_text":"El cual tenía un incensario de oro, y el arca del pacto cubierta de todas partes alrededor de oro; en la que estaba una urna de oro que contenía el maná, y la vara de Aarón que reverdeció, y las tablas del pacto;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-017","type":"choice","level":"hard","testament":"nt","book":"1PE","chapter":5,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Em 1 Pedro 5:13, a quem chama Pedro «meu filho»?","bible_ref":"1 Pedro 5:13","verse_text":"Saúda-vos a igreja escolhida convosco, que está na Babilônia, e também o meu filho Marcos."},"fr":{"prompt":"Dans 1 Pierre 5:13, qui Pierre appelle-t-il « mon fils » ?","bible_ref":"1 Pierre 5:13","verse_text":"L’Église des élus qui est à Babylone vous salue, ainsi que Marc, mon fils."},"en":{"prompt":"In 1 Peter 5:13, whom does Peter call “my son”?","bible_ref":"1 Peter 5:13","verse_text":"The church that is at Babylon, elected together with you, saluteth you; and so doth Marcus my son."},"es":{"prompt":"En 1 Pedro 5:13, ¿a quién llama Pedro «mi hijo»?","bible_ref":"1 Pedro 5:13","verse_text":"La iglesia que está en Babilonia, juntamente elegida con vosotros, os saluda, y Marcos mi hijo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Marcos"},"fr":{"text":"Marc"},"en":{"text":"Marcus"},"es":{"text":"Marcos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Silvano"},"fr":{"text":"Silvain"},"en":{"text":"Silvanus"},"es":{"text":"Silvano"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Timóteo"},"fr":{"text":"Timothée"},"en":{"text":"Timothy"},"es":{"text":"Timoteo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tito"},"fr":{"text":"Tite"},"en":{"text":"Titus"},"es":{"text":"Tito"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-018","type":"choice","level":"hard","testament":"nt","book":"2PE","chapter":3,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Em 2 Pedro 3:15, que irmão diz Pedro que também lhes escreveu, segundo a sabedoria que lhe foi dada?","bible_ref":"2 Pedro 3:15","verse_text":"E considerai como salvação a paciência de nosso Senhor; assim como também nosso irmão Paulo vos escreveu, segundo a sabedoria que lhe foi dada;"},"fr":{"prompt":"Dans 2 Pierre 3:15, quel frère Pierre dit-il leur avoir aussi écrit, selon la sagesse qui lui a été donnée ?","bible_ref":"2 Pierre 3:15","verse_text":"Croyez que la patience de notre Seigneur est votre salut, comme notre bien-aimé frère Paul vous l’a aussi écrit, selon la sagesse qui lui a été donnée."},"en":{"prompt":"In 2 Peter 3:15, which brother does Peter say also wrote to them, according to the wisdom given him?","bible_ref":"2 Peter 3:15","verse_text":"And account that the longsuffering of our Lord is salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you;"},"es":{"prompt":"En 2 Pedro 3:15, ¿qué hermano dice Pedro que también les escribió, según la sabiduría que le fue dada?","bible_ref":"2 Pedro 3:15","verse_text":"Y tened por salud la paciencia de nuestro Señor; como también nuestro amado hermano Pablo, según la sabiduría que le ha sido dada, os ha escrito también;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Paulo"},"fr":{"text":"Paul"},"en":{"text":"Paul"},"es":{"text":"Pablo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"João"},"fr":{"text":"Jean"},"en":{"text":"John"},"es":{"text":"Juan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Judas"},"fr":{"text":"Jude"},"en":{"text":"Jude"},"es":{"text":"Judas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tiago"},"fr":{"text":"Jacques"},"en":{"text":"James"},"es":{"text":"Jacobo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-019","type":"choice","level":"hard","testament":"nt","book":"1JN","chapter":2,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Segundo 1 João 2:18, por que sabemos que é a última hora?","bible_ref":"1 João 2:18","verse_text":"Filhinhos, é a última hora. E como ouvistes que o anticristo vem, já agora muitos anticristos chegaram. Por isso sabemos que é a última hora."},"fr":{"prompt":"Selon 1 Jean 2:18, à quoi connaissons-nous que c’est la dernière heure ?","bible_ref":"1 Jean 2:18","verse_text":"Petits enfants, c’est la dernière heure, et comme vous avez appris qu’un antéchrist vient, il y a maintenant plusieurs antéchrists: par là nous connaissons que c’est la dernière heure."},"en":{"prompt":"According to 1 John 2:18, whereby do we know that it is the last time?","bible_ref":"1 John 2:18","verse_text":"Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time."},"es":{"prompt":"Según 1 Juan 2:18, ¿por qué sabemos que es el último tiempo?","bible_ref":"1 Juan 2:18","verse_text":"Hijitos, ya es el último tiempo: y como vosotros habéis oído que el anticristo ha de venir, así también al presente han comenzado á ser muchos anticristos; por lo cual sabemos que es el último tiempo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Porque já vieram muitos anticristos"},"fr":{"text":"Parce qu’il y a plusieurs antéchrists"},"en":{"text":"Because there are many antichrists"},"es":{"text":"Porque han comenzado a ser muchos anticristos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Porque o templo caiu"},"fr":{"text":"Parce que le temple est tombé"},"en":{"text":"Because the temple has fallen"},"es":{"text":"Porque el templo ha caído"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Porque houve um terramoto"},"fr":{"text":"Parce qu’il y a eu un tremblement de terre"},"en":{"text":"Because there was an earthquake"},"es":{"text":"Porque hubo un terremoto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Porque o sol escureceu"},"fr":{"text":"Parce que le soleil s’est obscurci"},"en":{"text":"Because the sun was darkened"},"es":{"text":"Porque el sol se oscureció"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-020","type":"choice","level":"hard","testament":"nt","book":"3JN","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo 3 João 1:9, quem, na igreja, busca ser o comandante e não recebe quem escreve?","bible_ref":"3 João 1:9","verse_text":"Eu tenho escrito aos da igreja; porém Diótrefes, que busca ser o comandante deles, não nos recebe."},"fr":{"prompt":"Selon 3 Jean 1:9, qui, dans l’Église, aime à être le premier et ne reçoit pas celui qui écrit ?","bible_ref":"3 Jean 1:9","verse_text":"J’ai écrit quelques mots à l’Église; mais Diotrèphe, qui aime à être le premier parmi eux, ne nous reçoit point."},"en":{"prompt":"According to 3 John 1:9, who in the church loveth to have the preeminence and receiveth not the writer?","bible_ref":"3 John 1:9","verse_text":"I wrote unto the church: but Diotrephes, who loveth to have the preeminence among them, receiveth us not."},"es":{"prompt":"Según 3 Juan 1:9, ¿quién ama tener el primado en la iglesia y no recibe a quien escribe?","bible_ref":"3 Juan 1:9","verse_text":"Yo he escrito á la iglesia: mas Diótrefes, que ama tener el primado entre ellos, no nos recibe."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Diótrefes"},"fr":{"text":"Diotrèphe"},"en":{"text":"Diotrephes"},"es":{"text":"Diótrefes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Demétrio"},"fr":{"text":"Démétrius"},"en":{"text":"Demetrius"},"es":{"text":"Demetrio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Gaio"},"fr":{"text":"Gaïus"},"en":{"text":"Gaius"},"es":{"text":"Gaio"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Árquipo"},"fr":{"text":"Archippe"},"en":{"text":"Archippus"},"es":{"text":"Archîpo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"cartas2-hard-021","type":"choice","level":"hard","testament":"nt","book":"REV","chapter":2,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Apocalipse 2:13, como se chamava a fiel testemunha que foi morta onde Satanás habita?","bible_ref":"Apocalipse 2:13","verse_text":"Eu conheço tuas obras, e onde habitas, que é onde está o trono de Satanás; e tu reténs meu nome, e não negaste minha fé, até mesmo nos dias em que Antipas, que era minha fiel testemunha, o qual foi morto entre vós, onde Satanás habita."},"fr":{"prompt":"Selon Apocalypse 2:13, comment s’appelait le témoin fidèle mis à mort là où Satan a sa demeure ?","bible_ref":"Apocalypse 2:13","verse_text":"Je sais où tu demeures, je sais que là est le trône de Satan. Tu retiens mon nom, et tu n’as pas renié ma foi, même aux jours d’Antipas, mon témoin fidèle, qui a été mis à mort chez vous, là où Satan a sa demeure."},"en":{"prompt":"According to Revelation 2:13, what was the name of the faithful martyr who was slain where Satan dwelleth?","bible_ref":"Revelation 2:13","verse_text":"I know thy works, and where thou dwellest, even where Satan’s seat is: and thou holdest fast my name, and hast not denied my faith, even in those days wherein Antipas was my faithful martyr, who was slain among you, where Satan dwelleth."},"es":{"prompt":"Según Apocalipsis 2:13, ¿cómo se llamaba el testigo fiel que fue muerto donde Satanás mora?","bible_ref":"Apocalipsis 2:13","verse_text":"Yo sé tus obras, y dónde moras, donde está la silla de Satanás; y retienes mi nombre, y no has negado mi fe, aun en los días en que fué Antipas mi testigo fiel, el cual ha sido muerto entre vosotros, donde Satanás mora."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Antipas"},"fr":{"text":"Antipas"},"en":{"text":"Antipas"},"es":{"text":"Antipas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Estêvão"},"fr":{"text":"Étienne"},"en":{"text":"Stephen"},"es"