select public.upsert_bank_question($json${"id":"cartas2-hard-025","type":"verse","level":"hard","testament":"nt","book":"TIT","chapter":1,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Um próprio profeta deles disse: Os cretenses sempre são _____, animais malignos, ventres preguiçosos.","bible_ref":"Tito 1:12","verse_text":"Um próprio profeta deles disse: Os cretenses sempre são mentirosos, animais malignos, ventres preguiçosos."},"fr":{"prompt":"L’un d’entre eux, leur propre prophète, a dit: Crétois toujours _____, méchantes bêtes, ventres paresseux.","bible_ref":"Tite 1:12","verse_text":"L’un d’entre eux, leur propre prophète, a dit: Crétois toujours menteurs, méchantes bêtes, ventres paresseux."},"en":{"prompt":"One of themselves, even a prophet of their own, said, The Cretians are alway _____, evil beasts, slow bellies.","bible_ref":"Titus 1:12","verse_text":"One of themselves, even a prophet of their own, said, The Cretians are alway liars, evil beasts, slow bellies."},"es":{"prompt":"Dijo uno de ellos, propio profeta de ellos: Los Cretenses, siempre _____, malas bestias, vientres perezosos.","bible_ref":"Tito 1:12","verse_text":"Dijo uno de ellos, propio profeta de ellos: Los Cretenses, siempre mentirosos, malas bestias, vientres perezosos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"mentirosos"},"fr":{"text":"menteurs"},"en":{"text":"liars"},"es":{"text":"mentirosos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"orgulhosos"},"fr":{"text":"orgueilleux"},"en":{"text":"proud"},"es":{"text":"soberbios"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"covardes"},"fr":{"text":"lâches"},"en":{"text":"cowards"},"es":{"text":"cobardes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"ladrões"},"fr":{"text":"voleurs"},"en":{"text":"thieves"},"es":{"text":"ladrones"}}}]}$json$::jsonb);
